package main

import (
	"context"
	"flag"
	"fmt"
	"os"
	"os/signal"
	"syscall"

	"github.com/maximhq/bifrost/transports/bifrost-http/server"
)

func run(args []string) error {
	flags := flag.NewFlagSet("sfactory-gateway", flag.ContinueOnError)
	flags.SetOutput(os.Stderr)
	socketFD := flags.Int("socket-fd", -1, "inherited bound socket")
	socketPath := flags.String("socket-path", "", "protected socket path")
	configFD := flags.Int("bootstrap-fd", -1, "inherited sealed bootstrap")
	readyFD := flags.Int("cold-ready-fd", -1, "inherited readiness pipe")
	if flags.Parse(args) != nil || flags.NArg() != 0 || *socketFD < 3 || *configFD < 3 || *readyFD < 3 || *socketFD == *configFD || *socketFD == *readyFD || *configFD == *readyFD {
		return fmt.Errorf("factory gateway arguments refused")
	}
	ctx, cancel := signal.NotifyContext(context.Background(), syscall.SIGTERM, syscall.SIGINT)
	defer cancel()
	return server.RunFactoryGatewayCommand(ctx, os.NewFile(uintptr(*configFD), "bootstrap"), os.NewFile(uintptr(*readyFD), "cold-ready"), os.NewFile(uintptr(*socketFD), "bound-socket"), *socketPath)
}
func main() {
	if err := run(os.Args[1:]); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}
